import Foundation

struct GuideEntry:Identifiable {
    let title:String
    let text:String
    var id:String{title}
}
struct GuideTopic:Identifiable {
    let id:String
    let title:String
    let subtitle:String
    let icon:String
    let entries:[GuideEntry]
    var serviceOnly=false
    func matches(_ query:String)->Bool{query.isEmpty || ([title,subtitle]+entries.flatMap{[$0.title,$0.text]}).contains{$0.localizedCaseInsensitiveContains(query)}}
}
enum GuideCatalogue {
    static func topics(services:Bool)->[GuideTopic]{all.filter{services || !$0.serviceOnly}}
    static let all:[GuideTopic]=[
        GuideTopic(id:"image-effects",title:"تأثيرات الصور",subtitle:"مكتبة من ١٣ تأثيرًا وصورة أصلية محفوظة",icon:"photo.stack",entries:[
            GuideEntry(title:"الصورة الأصلية أو طبقة صورة",text:"افتح تأثيرات الصورة من شريط الأدوات الرئيسي لتطبيقها على صورة العمل. عند تحديد صورة مستوردة، افتح التأثيرات من أدوات تلك الطبقة. تبقى الصورة الأصلية محفوظة، وتُخزّن التأثيرات كإعدادات قابلة للتعديل."),
            GuideEntry(title:"المكتبة",text:"تحتوي بطاقات معاينة للتمويه وفصل قنوات اللون والخلل الرقمي وتظليل الأطراف والحبيبات والتوهج والفسيفساء ونقاط الطباعة والتقسيم والتلاشي وثنائي اللون والانعكاس والحافة الخارجية. اضغط البطاقة لإضافتها إلى التكديس."),
            GuideEntry(title:"التكديس والتحكم",text:"تُطبّق التأثيرات من الأعلى للأسفل. افتح التأثير لتعديل قوته وألوانه وزاويته وشفافيته أو نوعه حسب الأداة. استخدم سهمي الترتيب لتغيير النتيجة، ومفتاح التفعيل للمقارنة، وسلة الحذف لإزالة تأثير واحد. زر الأصل يمسح التأثيرات مع إبقاء الصورة والطبقات الأخرى."),
            GuideEntry(title:"الحفظ والدقة",text:"زر تم يحفظ الإعدادات مع المشروع. تدعم العمليات التراجع والإعادة والنسخ الاحتياطي وتصدير المشروع القابل للتعديل. أثناء تغيير القيم تظهر معاينة محدودة الحجم، ثم تتحسن بعد الاستقرار. تصدير PNG يحافظ على أبعاد اللوحة ويُعالج أجزاء الصورة دون اختزال أبعادها. الحبيبات ثابتة بين المعاينة والتصدير، ويمكن تغيير توزيعها بزر توزيع جديد.")]),
        GuideTopic(id:"start",title:"مسار عملك الأول",subtitle:"من صور الفصل إلى نسخة جاهزة للنشر",icon:"sparkles",entries:[
            GuideEntry(title:"١ · جهّز الفصل",text:"من الصفحة الرئيسية اختر استيراد الصور. اختيار صورة واحدة ينشئ مشروعًا، واختيار عدة صور يجمعها في فصل مستورد. يمكنك إنشاء فصل فارغ وإضافة صفحاته لاحقًا، أو إنشاء مجلد باسم العمل ومجلدات لفصوله."),
            GuideEntry(title:"٢ · جهّز الحوارات",text:"افتح التايبر من الصفحة الرئيسية. أنشئ نص الفصل يدويًا أو استورد TXT، ثم اختر فصل النص كل سطر أو كل فقرة. أضف بادئة الوسم قبل الحوار لتعيين نمط الراوي أو التفكير أو الصراخ."),
            GuideEntry(title:"٣ · نظّف وضع النص",text:"افتح الصفحة في المحرر. استخدم القنص لتحديد الفقاعات ثم تبييضها، وراجع النتيجة قبل اعتمادها. افتح لوحة التايبر لإدراج الحوار التالي، أو اسحب مساحة الفقاعة بأداة تنسيق فقاعة."),
            GuideEntry(title:"٤ · راجع واحفظ",text:"راجع النصوص والمقابض والطبقات، ثم صدّر PNG للنشر بالأبعاد الأصلية. احفظ المشروع أيضًا لتبقى النصوص والطبقات قابلة للتعديل. استخدم النسخ الاحتياطي لنقل مكتبتك إلى مكان آخر.")]),
        GuideTopic(id:"library",title:"المعرض والمجلدات",subtitle:"تنظيم الأعمال والفصول وفتح المشاريع",icon:"folder",entries:[
            GuideEntry(title:"المعرض",text:"يعرض المشاريع والمجلدات والفصول. ابحث بالاسم، وافتح الصورة لبدء التحرير أو الفصل لعرض صفحاته. بطاقة المشروع تعرض معاينة، وبطاقة الفصل تعرض عدد الصفحات."),
            GuideEntry(title:"المجلدات والفصول",text:"زر المجلد الجديد ينشئ مجلدًا داخل المكان الحالي. يمكنك مثلًا إنشاء مجلد للعمل، وداخله مجلد لكل فصل. الفصل نفسه يجمع صفحات مرتبة، ويدعم التصدير والقراءة والعمليات الجماعية."),
            GuideEntry(title:"إدارة المشروع",text:"اضغط مطولًا على البطاقة لتغيير الاسم أو نقلها إلى مجلد آخر أو حذفها. حذف المشروع ليس هو تنظيف الملفات المؤقتة؛ انسخ أعمالك المهمة قبل الحذف."),
            GuideEntry(title:"فتح الملفات",text:"فتح مشروع يقبل ملفات Cookies والفصول والصور وPDF والحزم المدعومة. عند استخدام الملفات حدّد الملف ثم اضغط تم. انتظر انتهاء الاستيراد؛ الخطوط والمشاريع الكبيرة تحتاج وقتًا للتجهيز.")]),
        GuideTopic(id:"chapter",title:"استوديو الفصل",subtitle:"استيراد وسحب وترتيب ودمج وتقسيم",icon:"rectangle.stack",entries:[
            GuideEntry(title:"ترتيب الصفحات",text:"تظهر الصفحات حسب ترتيب الفصل. افتح أي صفحة لتحريرها. اضغط مطولًا لتقديمها أو تأخيرها أو جعلها غلاف الفصل. في وضع التحديد اختر بعض الصفحات أو الكل لتنفيذ عملية جماعية."),
            GuideEntry(title:"سحب الفصل",text:"افتح أداة سحب الفصل وأدخل رابط الصفحة. تصفّح الموقع، ثم استخدم تمريرًا تلقائيًا لتحميل الصور الكسولة. افتح قائمة الصور، راجع ترتيبها وأبعادها واحذف ما لا يخص الفصل، ثم نزّل المحدد. مواقع لا تعرض الصور مباشرة أو تتطلب صلاحيات خاصة قد لا تسمح بالسحب."),
            GuideEntry(title:"الدمج والتقسيم",text:"الدمج يضم الصفحات المحددة رأسيًا مع اختيار المحاذاة إذا اختلف العرض، ويحافظ على محتواها وطبقاتها. التقسيم يكون بطول الجزء أو عدد الأجزاء. تغيير المقاس يحجّم المحتوى أو يغيّر مساحة اللوحة، بحسب الخيار المحدد."),
            GuideEntry(title:"عمليات إضافية",text:"يمكن إنشاء لوحة فارغة، تغيير أسماء الصفحات، نقلها إلى فصل آخر، أو استعادة صفحات الفصل قبل آخر عملية. راجع عدد الصفحات المختارة في شريط الأدوات قبل التنفيذ."),
            GuideEntry(title:"تصدير الفصل والقراءة",text:"تصدير الفصل يدعم PNG وJPEG وPSD والمشاريع وفصلًا قابلًا للتعديل. التصدير الذكي يدمج ثم يقسّم إلى الطول الذي تختاره. القارئ يتذكر الصفحة وموضع القراءة؛ اتجاه انتقال الصفحات قابل للتعديل في الإعدادات.")]),
        GuideTopic(id:"canvas",title:"المحرر والتفاعل",subtitle:"التحريك والتكبير والمقابض والتراجع",icon:"hand.draw",entries:[
            GuideEntry(title:"التكبير والتحريك",text:"قرّب بإصبعين، وتحرك داخل الصورة للوصول إلى موضع العمل. في وضع الرسم استخدم إصبعين لتحريك اللوحة حتى لا تُرسم ضربة بالخطأ. الصورة الأصلية منفصلة عن الطبقات، ولا يغيّر التكبير أبعادها."),
            GuideEntry(title:"أوضاع الأدوات",text:"الشريط الرئيسي يعرض النص والرسم والصور والأشكال والتنسيق والتايبر والقنص والتنظيف والقطارة واستبدال الأصل والقراءة مباشرة. عند اختيار النص أو الرسم تظهر أدوات ذلك الوضع مكان الشريط الرئيسي. زر الرجوع داخل الشريط يعيدك إلى الأدوات الرئيسية."),
            GuideEntry(title:"مقابض النص والعناصر",text:"المس العنصر لتحديده. اسحب جسمه لتحريكه، واستخدم مقابض الدوران والمقاس والعرض والارتفاع. تظل المقابض والعناصر قابلة للتفاعل خارج حدود الصورة. زر النسخ يكرر الطبقة، وزر التعديل يفتح محتواها، وزر الأنماط يفتح المكتبة."),
            GuideEntry(title:"التراجع والإعادة",text:"السهمان في الشريط العلوي يتراجعان عن عمليات التحرير ويعيدانها. الأبيض يعني أن الإجراء متاح، والرمادي يعني أن القائمة فارغة. عند بدء تعديل جديد بعد التراجع تُلغى قائمة الإعادة."),
            GuideEntry(title:"حدود دقة الصورة",text:"التكبير لا يولّد تفاصيل جديدة داخل صورة نقطية: عند تجاوز دقتها قد ترى بكسلات الأصل نفسه. تُرسم النصوص من بيانات الخط بحسب العرض والتصدير؛ احفظ المشروع للحفاظ على قابليتها للتعديل. PNG يحافظ على الدقة الأصلية، بينما JPEG يضغط الصورة مع فقدان.")]),
        GuideTopic(id:"text",title:"النص والتأثيرات",subtitle:"الخط والتدرج والحدود والمنظور والتنسيق",icon:"textformat",entries:[
            GuideEntry(title:"إضافة النص ومحتواه",text:"اختر نص ثم إضافة نص. يبدأ النص اليدوي بأسود بلا حدود أو مؤثرات. بعد تأكيد إعداداته بزر تم يتذكر الخط واللون والتأثيرات للنصوص اليدوية التالية فقط، مستقلة عن الوسوم والقنص والتنسيق. لون الكتابة داخل لوحة المحتوى أبيض لقراءته على الخلفية الداكنة، مع إبقاء الخط المختار؛ لون النص على الصورة يبقى كما ضبطته. يمكن تفعيل اقتراح نضيف نص؟ عند لمس مساحة فارغة من إعدادات التحرير."),
            GuideEntry(title:"الخط والتنسيق والتباعد",text:"اختر الخط من اللوحة أو افتح المكتبة داخل المحرر. اضبط الحجم والمحاذاة والتغميق والميل وخطّي التسطير والشطب. أدوات التباعد تتحكم في الحروف والأسطر وعرض صندوق النص. بجانب أشرطة الضبط زر زائد وناقص للتغيير بخطوة محددة."),
            GuideEntry(title:"اللون والتدرج",text:"اللون يطبّق على حروف النص. التدرج يملأ الحروف أيضًا؛ يمكنك ضبط ألوانه ومحطاته ونوعه واتجاهه ونقاطه. خرائط التدرج توفر مجموعات جاهزة قابلة للتعديل. خلفية النص أداة منفصلة لها لون وشفافية ومسافة وزوايا."),
            GuideEntry(title:"الحدود والظل",text:"الحد يحيط بالحروف من الخارج ويُرسم أسفل تعبئتها، فلا يستبدل لونها أو تدرجها. اضبط السماكة واللون أو التدرج، وأضف حدودًا متعددة عند الحاجة. الظل يتيح اللون والتمويه والإزاحة والشفافية."),
            GuideEntry(title:"الموضع والمنظور والأبعاد",text:"الموضع يضبط التحريك والمقاس والدوران. المنظور يغيّر شكل النص بمقابض الزوايا أو شبكة التشويه. الأبعاد تضيف عمقًا مرسومًا. هذه العمليات تخص الطبقة المحددة؛ الصورة الأصلية تبقى مستقلة."),
            GuideEntry(title:"الخامة والقناع والتأثيرات",text:"الخامة تملأ الحروف بصورة أو خامة يمكن تحجيمها وتحريكها وتدويرها. القناع يخفي أجزاء من النص أو يعيد إظهارها دون حذف محتواه. التأثيرات تضيف التمويه أو التوهج أو التقطيع وغيرها. كل أثر له ضوابطه، ويمكن العودة إلى بلا تأثير.")]),
        GuideTopic(id:"typer",title:"التايبر والوسوم",subtitle:"الفقاعات والألوان والاستئناف والتوزيع",icon:"text.bubble",entries:[
            GuideEntry(title:"ملف الفصل والوسوم",text:"أضف ملف TXT بترميز UTF-8 أو UTF-16، أو اكتب النص يدويًا. كل سطر أو فقرة تصبح فقاعة. أمثلة البادئات: # للراوي، () للتفكير، : للصراخ، $ للنظام، ** للمؤثرات، [] لمربع النص، و## لعنوان لا يُدرج. // يواصل وسم الحوار السابق. تستطيع تعديل البادئات والمجموعات."),
            GuideEntry(title:"لوحة التحرير العائمة",text:"افتح التايبر من الشريط أو زر كوكيز العائم. اختر الفصل ثم فقاعة لإدراجها، أو استخدم الفقاعة التالية. تبقى اللوحة فوق المحرر دون إغلاقه، ويمكن إغلاقها والعودة إليها. تحفظ الفلتر والبحث وخيارات الإدراج؛ تظهر الفقاعة التالية بعد آخر استخدام تلقائيًا، وزر موضعي يعيدك إليها."),
            GuideEntry(title:"التقدّم والفلاتر",text:"تتحول الفقاعة المستخدمة إلى الرمادي مع علامة، ويُحفظ ذلك في الفصل. اختر الكل أو المتبقية أو المستخدمة. من الضغط المطول يمكنك إعادة فقاعة إلى المتبقية أو تحديدها كمستخدمة أو نسخ نصها أو تعديلها وترتيبها."),
            GuideEntry(title:"ألوان الوسوم وأنماطها",text:"لكل وسم لون تعريف يظهر في شريط بطاقته وعنوانها. غيّره من إعدادات التايبر عبر تحرير الوسم. هذا اللون لا يغيّر لون النص المدرج. القنص والتنسيق يستخدمان نمط وسم الفقاعة نفسه، بما فيه الحوار العادي بلا بادئة. اضغط تصميم النمط داخل المحرر لتجربة أدوات النص كاملة، ثم حفظ الوسم وتأكيده."),
            GuideEntry(title:"خيارات الإدراج",text:"خيارات اللوحة تتيح اختيار وسم بديل أو خط سريع، وتحويل الأحرف اللاتينية إلى كبيرة، واختيار تنسيق مربع أو دائرة. اختيار وسم الفقاعة يعيد نمط كل حوار الأصلي. يمكنك تحديد بداية التوزيع بالضغط المطول على الفقاعة."),
            GuideEntry(title:"المسودات والنسخ",text:"يُحفظ نص التحرير كمسودة أثناء الكتابة. مكتبة التايبر تعرض المسودات والفصول المحذوفة للاسترجاع. يمكنك تصدير TXT أو فصل مع حالته، وإدارة مجموعات وسوم مستقلة. النسخ الاحتياطي يشمل نصوص التايبر وألوانه وخيارات لوحته.")]),
        GuideTopic(id:"sniper",title:"القنص وتنسيق الفقاعة",subtitle:"اختيار الحدود وإدراج النص بمقاس مناسب",icon:"scope",entries:[
            GuideEntry(title:"القنص",text:"المس داخل فقاعة لتحديد داخلها وحدودها، ثم تابع الفقاعات بالترتيب. زر تراجع يزيل آخر هدف. افتح التايبر واختر إدراج الأهداف لوضع الحوارات التالية بحسب ترتيبها. العناوين والفقاعات المستخدمة تُتجاوز تلقائيًا."),
            GuideEntry(title:"التنسيق بحسب الشكل",text:"تنسيق فقاعة يتيح سحب منطقة داخل الفقاعة واختيار شكل بيضاوي أو صراخ أو مربع أو مستطيل أو نظام. يوزّع الكلمات على أسطر حسب مساحة المنطقة ويختار حجم الخط، مع هامش عن الحواف. الفقاعات الدائرية تجعل الأسطر الوسطى أطول، والمربعات تميل إلى توزيع متقارب العرض."),
            GuideEntry(title:"النمط والتقدّم",text:"يُستخدم وسم الفقاعة ونمطه عند الإدراج، ثم تُعلّم الفقاعة كمستخدمة ويتقدم الفصل. القنص يعتمد حدود الفقاعة المكتشفة بدل منطقة مرسومة فقط. تستطيع تعديل النص والمقاس والمقابض بعد الإدراج إذا احتاج شكل غير معتاد إلى مراجعة."),
            GuideEntry(title:"نتيجة أدق",text:"المس مساحة داخل الفقاعة بعيدًا عن إطارها، وراجع الهدف المكتشف قبل التنفيذ. الأسطر الطويلة جدًا، الحدود المفتوحة، الزخارف، والمحتوى المتداخل قد تحتاج إلى تحديد يدوي أو مراجعة. لا يجعل التنسيق كل الفقاعات المختلفة متطابقة بصريًا.")]),
        GuideTopic(id:"cleaning",title:"التبييض والتنظيف والرسم",subtitle:"إزالة النصوص والفرشاة والممحاة والقطارة",icon:"eraser",entries:[
            GuideEntry(title:"تبييض بالقنص",text:"حدد الفقاعات بالقنص ثم اختر تبييض النص. يعالج النص داخل المنطقة مع حماية حدودها. تظهر نتائج للمراجعة؛ قارن بالأصل ثم اعتمد النتيجة أو ألغها. العملية قابلة للتراجع بعد اعتمادها."),
            GuideEntry(title:"الخلفيات المختلفة",text:"الفقاعات البيضاء المسطحة تناسب التعبئة النظيفة. التدرجات والألوان تُعالَج بحسب الخلفية المحيطة. في الخلفيات المزخرفة أو الرسومات خلف النص لا يمكن ضمان استعادة الرسم المخفي تمامًا؛ راجع المعاينة واستخدم الفرشاة أو التنظيف الموضعي لإكماله."),
            GuideEntry(title:"التنظيف اليدوي",text:"اختر تنظيف وارسم فوق الحروف التي تريد إزالتها. يعرض التطبيق إعادة البناء للمراجعة، ولا يعتمدها قبل موافقتك. نصف قطر إعادة البناء قابل للتعديل في إعدادات مساحة العمل."),
            GuideEntry(title:"الفرشاة",text:"اختر رسم ثم اللون والحجم. تتوفر فرشاة صلبة أو مائية أو مضيئة أو ناعمة أو تحديد أو خامة، ورسم حر أو خط أو مستطيل أو دائرة. يمكن تعبئة الأشكال، والتعبئة اللونية لها تسامح، والطمس له قوة. الرسم يظهر أثناء حركة الإصبع، ومعاينة مكبرة تساعد على رؤية موضع اللمس."),
            GuideEntry(title:"الممحاة",text:"تعمل على طبقة الرسم المختارة. تظهر دائرة فارغة عند اللمس تمثل حجم المسح، وتتغير مع الحجم والتكبير. مسح طبقة الرسم لا يمحو الصورة الأصلية؛ لتنظيف النص الموجود فيها استخدم التبييض أو التنظيف."),
            GuideEntry(title:"القطارة",text:"اضغط مطولًا على الصورة أو اختر القطارة. تظهر دائرة بإطار أبيض فوق إصبعك وبداخلها اللون الملتقط ورمزه. حرّك الإصبع لاختيار لون آخر، وارفعه لاعتماده للفرشاة ولون النص المحدد. لا تظهر الدائرة في الصورة المصدّرة.")]),
        GuideTopic(id:"layers",title:"الطبقات والأنماط والخطوط",subtitle:"تحرير منظم ومكتبات تخصك",icon:"square.3.layers.3d",entries:[
            GuideEntry(title:"إدارة الطبقات",text:"افتح الطبقات من الشريط العلوي. كل نص أو صورة أو شكل أو رسم طبقة مستقلة. العين تخفي الطبقة، والقفل يمنع تعديلها، والحذف يزيلها. اختر الطبقة لتعديلها، واسحب ترتيبها لتغيير ما يظهر فوق الآخر. تتوفر فلاتر لأنواع الطبقات."),
            GuideEntry(title:"الجمع والمعاينة",text:"التحديد المتعدد يسمح بدمج طبقات أو تجميعها وفك التجميع. التسطيح يحوّل العمل إلى صورة مع إمكانية التراجع. اضبط الشفافية ووضع المزج. المعاينة المكبرة تقبل خلفية شفافية أو فاتحة أو داكنة لتظهر النصوص البيضاء والسوداء؛ الخلفية للمعاينة فقط."),
            GuideEntry(title:"الأنماط الخاصة",text:"حدد النص ثم افتح الأنماط، واحفظ نمطًا جديدًا باسم ومجموعة. تطبيقه ينقل خصائص النص، مع خيار تضمين عرض النص والمنظور. يمكنك إعادة تسمية النمط وتحديثه ونسخه وتصديره أو استيراد حزمة، ونسخ خصائص معينة ولصقها بدل كل النمط."),
            GuideEntry(title:"الخطوط",text:"مكتبة الخطوط تعرض مثالًا مع اسم الملف الأصلي. تصفّح العربية والإنجليزية والمفضلة وآخر استخدام والمستوردة ومجموعاتك. أضف TTF أو OTF أو حزمة خطوط من الملفات. يمكن استيراد الخط واختياره داخل المحرر، ووضع علامة مفضلة، وتصدير المحدد أو جمعه في مجموعة."),
            GuideEntry(title:"عند نقل المشروع",text:"الخطوط المستوردة والأنماط وخاماتها جزء من مكتبتك. استخدم النسخ الاحتياطي وحدد هذه الأقسام مع المشاريع عند نقل العمل لجهاز آخر، حتى لا يضيع الخط أو النمط الذي اعتمدت عليه.")]),
        GuideTopic(id:"storage",title:"الحفظ والمساحة والنسخ",subtitle:"أبعاد أصلية ونسخ انتقائية واستعادة حقيقية",icon:"externaldrive",entries:[
            GuideEntry(title:"حفظ المشروع والتصدير",text:"التعديلات محفوظة في المشروع. PNG يصدر الصورة بلا فقدان وبأبعادها الأصلية. JPEG يصدر بضغط وجودة تختارها. PSD يحتفظ بالطبقات مرسومة، وملف المشروع يحتفظ بالنصوص وخصائصها قابلة للتعديل. احفظ في الصور أو شارك الملف في مكان تختاره."),
            GuideEntry(title:"قياس المساحة",text:"الإعدادات ← المساحة والنسخ الاحتياطي تعرض الحجم الفعلي للملفات وأقسامها، ومساحة الجهاز المتاحة. الصور الطويلة وطبقاتها ومعايناتها تشغل مساحة؛ ضغط التصدير وحده لا يقلل تلقائيًا حجم مكتبة المشاريع."),
            GuideEntry(title:"النسخة الانتقائية",text:"اختر المشاريع والفصول والخطوط والأنماط والوسوم والإعدادات أو الكل، ثم أنشئ النسخة وشاركها إلى الملفات أو مكان خارج التطبيق. عند الاستعادة افتح النسخة، راجع عناصرها، واختر ما تريد استعادته فقط. احتفظ بالنسخة خارج بيانات التطبيق قبل الحذف."),
            GuideEntry(title:"تنظيف الملفات المؤقتة",text:"مسح المؤقتات يزيل الملفات التي يمكن إعادة توليدها، ولا يحذف أصل المشاريع أو خطوطك. يمكن حذف مجموعات بيانات محددة من واجهة المساحة. إعادة ضبط التطبيق كاملة تحذف المشاريع والمكتبات والإعدادات وجلسة الحساب المحلية وتعيد شاشة البداية."),
            GuideEntry(title:"الإعدادات والتقارير",text:"المظهر يضبط مقاسات الأدوات والحركة، والتحرير يضبط المقابض وإضافة النص، والمعاينة تضبط تفاصيل العرض، والقراءة تضبط اتجاه الصفحات. تقارير الأداء والأعطال تساعد في شرح مشكلة ومشاركة سجلها عند الحاجة.")]),
        GuideTopic(id:"community",title:"الحساب والمجتمع",subtitle:"الدخول والملف الشخصي والمنشورات",icon:"person.2",entries:[
            GuideEntry(title:"الحساب",text:"يمكن التحرير دون تسجيل دخول. الحساب يتيح خدمات المجتمع. استخدم بريدك وكلمة المرور أو Google عندما تسمح إعدادات الخدمة بذلك. إنشاء حساب جديد قد يتطلب تأكيد البريد، ويمكن إعادة طلب الرسالة بعد انتهاء مهلة الإرسال."),
            GuideEntry(title:"المجتمع",text:"تصفّح المنشورات وأعمال المجتمع، وافتح المنشور لقراءة التفاصيل والتعليقات. عند تسجيل الدخول يمكنك التفاعل والتعليق بحسب ما تسمح به الخدمة. تظهر أخطاء الاتصال برسالة، ويمكن إعادة المحاولة."),
            GuideEntry(title:"الملف الشخصي",text:"يعرض معلومات حسابك وإحصاءات الفقاعات والنقاط والعضوية التي ترجعها الخدمة. أدوات التحرير المحلية لا تتطلب نقاطًا. النقاط والعضوية التابعة للخدمة لا تتغير بمجرد تثبيت التطبيق."),
            GuideEntry(title:"إذا تعذر الدخول",text:"راجع البريد وكلمة المرور ورسالة الخطأ. قبول طلب إنشاء الحساب لا يثبت وصول رسالة التأكيد. إذا انتهى Google في صفحة localhost ولم يرجع إلى التطبيق، فإعداد عودة الدخول لدى الخدمة يحتاج إلى تهيئة؛ لا تحل إعادة كتابة كلمة المرور هذا الإعداد.")],serviceOnly:true)
    ]
}
